	async function getObjectsFields(keys, fields = [], nullForMissing = false) {
		if (!Array.isArray(keys) || !keys.length) {
			return [];
		}
		if (!fields.length) {
			return await module.getObjects(keys);
		}

		const res = await module.pool.query({
			name: 'getObjectsFields',
			text: `
SELECT (SELECT jsonb_object_agg(f, d."value")
          FROM UNNEST($2::TEXT[]) f
          LEFT OUTER JOIN jsonb_each(h."data") d
                       ON d."key" = f) d,
       h."data" IS NOT NULL AS "exists"
  FROM UNNEST($1::text[]) WITH ORDINALITY k("_key", i)
  LEFT OUTER JOIN "legacy_object_live" o
               ON o."_key" = k."_key"
  LEFT OUTER JOIN "legacy_hash" h
               ON o."_key" = h."_key"
              AND o."type" = h."type"
 ORDER BY k.i ASC`,
			values: [keys, fields],
		});

		return res.rows.map(row => (nullForMissing && !row.exists ? null : row.d));
	}

	module.getObjectsFields = async function (keys, fields = []) {
		return await getObjectsFields(keys, fields);
	};

